// PADRONIZAR A LEITURA
// Aceita os dois formatos de JSON que existem no projeto:
//   firmware atual ...... {"ponto":"1","temperatura":24.5,"gas":573}
//   contrato do guia .... {"ponto":"ponto01","ts":"2026-11-20T21:00:00Z","temp_c":38.5,"gas_adc":2900,"estado":"alerta"}
// A saída usa sempre os nomes do guia: ponto, ts, temp_c, gas_adc (e estado, só se o firmware enviar).

function numero(v) {
    if (typeof v === 'number') { return v; }
    if (typeof v === 'string' && v.trim() !== '') { return Number(v); }
    return NaN;
}

const p = msg.payload;
if (p === null || typeof p !== 'object' || Array.isArray(p)) {
    node.warn('Mensagem ignorada: o payload não é um objeto JSON.');
    return null;
}

const temp = numero(p.temp_c !== undefined ? p.temp_c : p.temperatura);
const gas = numero(p.gas_adc !== undefined ? p.gas_adc : p.gas);

// O broker é público: qualquer pessoa pode publicar neste tópico.
// Só passam valores que os sensores conseguem medir (DHT22 e ADC de 12 bits do ESP32).
if (!(temp >= -40 && temp <= 125) || !(gas >= 0 && gas <= 4095)) {
    node.warn('Leitura ignorada (temperatura ou gás ausente/fora da faixa): ' + JSON.stringify(p));
    return null;
}

// Identificador do ponto: "1" vira "ponto1", igual ao nome usado no tópico.
let ponto = String(p.ponto === undefined || p.ponto === null ? '' : p.ponto).trim();
if (ponto === '') {
    const partes = String(msg.topic || '').split('/');
    ponto = partes.length >= 2 ? partes[partes.length - 2] : '';
}
if (/^\d+$/.test(ponto)) { ponto = 'ponto' + ponto; }
ponto = ponto.replace(/[^A-Za-z0-9_-]/g, '').slice(0, 32) || 'ponto';

// Horário da leitura em UTC. O firmware atual não envia "ts",
// então vale o instante em que a mensagem chegou ao Node-RED.
let quando = new Date();
if (typeof p.ts === 'string') {
    const enviado = new Date(p.ts);
    if (!isNaN(enviado.getTime()) && enviado.getUTCFullYear() >= 2020) { quando = enviado; }
}

const leitura = {
    ponto: ponto,
    ts: quando.toISOString().replace(/\.\d{3}Z$/, 'Z'),
    temp_c: Math.round(temp * 100) / 100,
    gas_adc: Math.round(gas)
};
if (['normal', 'alerta', 'prioridade_alta'].includes(p.estado)) { leitura.estado = p.estado; }

msg.payload = leitura;
return msg;

// REGRA AUTOMÁTICA DE ALERTA (guia da equipe, página 4)
//   - 3 leituras seguidas com gás ACIMA do limite ......... estado "alerta"
//   - em alerta, temperatura ACIMA do limite .............. estado "prioridade_alta"
//   - 3 leituras seguidas com gás no limite ou abaixo ..... volta para "normal"
//   - um pico isolado não muda o estado: a contagem recomeça quando a sequência é interrompida
// Se o firmware já enviar o campo "estado", o painel só acompanha o estado do firmware.

const LIMITE_GAS = 3000;       // contagens do ADC (mesmo valor do firmware)
const LIMITE_TEMP = 40;        // graus Celsius (mesmo valor do firmware)
const LEITURAS_SEGUIDAS = 3;   // leituras seguidas para confirmar ou encerrar o alerta

const l = msg.payload;
let pontos = context.get('pontos') || {};
if (!pontos[l.ponto] && Object.keys(pontos).length >= 50) { pontos = {}; }
const s = pontos[l.ponto] || { emAlerta: false, altas: 0, baixas: 0, estado: 'normal' };
const estadoAnterior = s.estado;

if (l.estado) {
    s.emAlerta = l.estado !== 'normal';
    s.altas = 0;
    s.baixas = 0;
    msg.origemEstado = 'firmware';
} else {
    if (l.gas_adc > LIMITE_GAS) {
        s.altas += 1;
        s.baixas = 0;
    } else {
        s.baixas += 1;
        s.altas = 0;
    }
    if (!s.emAlerta && s.altas >= LEITURAS_SEGUIDAS) { s.emAlerta = true; }
    if (s.emAlerta && s.baixas >= LEITURAS_SEGUIDAS) { s.emAlerta = false; }

    if (!s.emAlerta) {
        l.estado = 'normal';
    } else if (l.temp_c > LIMITE_TEMP) {
        l.estado = 'prioridade_alta';
    } else {
        l.estado = 'alerta';
    }
    msg.origemEstado = 'painel';
}

s.estado = l.estado;
pontos[l.ponto] = s;
context.set('pontos', pontos);

msg.estadoAnterior = estadoAnterior;
msg.limites = { gas: LIMITE_GAS, temp: LIMITE_TEMP };

const cores = { normal: 'green', alerta: 'yellow', prioridade_alta: 'red' };
node.status({ fill: cores[l.estado], shape: 'dot', text: l.ponto + ': ' + l.estado + ' | gás ' + l.gas_adc + ' | ' + l.temp_c + ' °C' });
return msg;

// AVISO DO PRÓPRIO ESP32
// O firmware publica este texto no tópico de alerta no mesmo instante em que liga o LED e o buzzer.
// Aqui só acrescentamos a hora em que o aviso chegou.
const hora = new Date().toLocaleTimeString('pt-BR');
msg.payload = hora + ' · ' + String(msg.payload).slice(0, 120);
return msg;

// CONEXÃO COM O BROKER
// Traduz o status do nó MQTT (verde, amarelo ou vermelho) para um texto simples no painel.
const textos = { green: 'conectado', yellow: 'conectando...', red: 'desconectado' };
const cor = msg.status ? msg.status.fill : '';
msg.payload = textos[cor] || 'desconectado';
return msg;

// GRÁFICOS
// Cada gráfico recebe duas séries: a medida e a linha do limite,
// para ficar visível quando a leitura passa do limite.
// Saída 1 = gráfico de temperatura. Saída 2 = gráfico de gás.
const l = msg.payload;
const lim = msg.limites;

return [
    [
        { topic: 'Temperatura (°C)', payload: l.temp_c },
        { topic: 'Limite (' + lim.temp + ' °C)', payload: lim.temp }
    ],
    [
        { topic: 'Gás (ADC)', payload: l.gas_adc },
        { topic: 'Limite (' + lim.gas + ')', payload: lim.gas }
    ]
];

// AVISO AUTOMÁTICO NA TELA
// Aparece só quando o estado MUDA (não a cada leitura) e diz qual ponto verificar.
const l = msg.payload;
if (l.estado === msg.estadoAnterior) { return null; }

const textos = {
    alerta: 'ALERTA no ' + l.ponto + ': gás acima do limite. Verificar o local.',
    prioridade_alta: 'PRIORIDADE ALTA no ' + l.ponto + ': gás e temperatura acima do limite. Verificar o local agora.',
    normal: 'O ' + l.ponto + ' voltou ao normal.'
};
const cores = { alerta: '#fab219', prioridade_alta: '#d03b3b', normal: '#0ca30c' };

return {
    topic: l.ponto,
    payload: textos[l.estado],
    ui_update: { color: cores[l.estado] }
};

// HISTÓRICO EM CSV
// Colunas pedidas no guia: ponto, ts, temp_c, gas_adc, estado (com UM único cabeçalho).
// Arquivo: <sua pasta de usuário>/vigia-coco/leituras_vigia_coco.csv  (o painel mostra o caminho completo)
// Para começar um CSV novo, apague ou renomeie o arquivo: ele é recriado na próxima leitura.
// Saída 1 = linha para o nó "Acrescentar ao CSV". Saída 2 = só reler o que já está gravado.

const COLUNAS = ['ponto', 'ts', 'temp_c', 'gas_adc', 'estado'];
const arquivo = path.join(os.homedir(), 'vigia-coco', 'leituras_vigia_coco.csv');
msg.filename = arquivo;

// Cabeçalho único: se o arquivo ainda não existe (ou está vazio), ele é criado só com o cabeçalho.
// Depois disso o nó "Acrescentar ao CSV" só acrescenta linhas de leitura.
if (!fs.existsSync(arquivo) || fs.statSync(arquivo).size === 0) {
    fs.mkdirSync(path.dirname(arquivo), { recursive: true });
    fs.writeFileSync(arquivo, COLUNAS.join(',') + os.EOL);
}

// Ao iniciar o Node-RED não há leitura para gravar: só relê o arquivo para preencher o painel.
if (msg.topic === 'iniciar') {
    return [null, msg];
}

const l = msg.payload;
msg.payload = COLUNAS.map(function (coluna) { return l[coluna]; }).join(',');
return [msg, null];

// RESUMO DO HISTÓRICO
// Recebe o conteúdo do CSV já convertido em objetos (uma linha = um objeto)
// e atualiza a tabela, o contador e o caminho do arquivo no painel.
// Saída 1 = tabela (10 leituras mais recentes). Saída 2 = total gravado. Saída 3 = caminho do arquivo.
const linhas = Array.isArray(msg.payload) ? msg.payload : [];

function horaLocal(ts) {
    const d = new Date(ts);
    if (isNaN(d.getTime())) { return String(ts); }
    return d.toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' });
}

const recentes = linhas.slice(-10).reverse().map(function (l) {
    return { hora: horaLocal(l.ts), ponto: l.ponto, temp_c: l.temp_c, gas_adc: l.gas_adc, estado: l.estado };
});

return [
    { payload: recentes },
    { payload: linhas.length },
    { payload: msg.filename }
];

// ERRO DE ARQUIVO
// Mostra um aviso na tela se o CSV não puder ser gravado ou lido
// (por exemplo, quando o arquivo está aberto no Excel).
const detalhe = (msg.error && msg.error.message) ? msg.error.message : 'erro desconhecido';
return { payload: 'Não foi possível gravar ou ler o CSV: ' + detalhe };

// SIMULADOR: roteiro com os 5 testes da página 5 do guia (22 leituras).
// O nó seguinte solta uma leitura por segundo.
const roteiro = [
    // Teste 01 - Normal: gás abaixo do limite
    [27.4, 620], [27.6, 580], [27.9, 710], [28.1, 640], [28.0, 690],
    // Teste 02 - Pico isolado: uma leitura alta seguida de baixas (o estado continua normal)
    [28.3, 3350], [28.2, 650], [28.4, 700],
    // Teste 03 - Alerta: três leituras altas seguidas, temperatura abaixo do limite
    [31.2, 3200], [32.5, 3320], [33.1, 3410],
    // Teste 04 - Prioridade alta: alerta ativo e temperatura acima do limite
    [41.5, 3380], [42.3, 3450], [43.0, 3300],
    // Temperatura cai, gás continua alto: volta de prioridade alta para alerta
    [36.4, 3260], [35.8, 3180],
    // Teste 05 - Retorno: três leituras com gás no limite ou abaixo
    [33.0, 900], [31.5, 760], [30.2, 680],
    // Segue normal
    [29.6, 640], [29.1, 610], [28.8, 590]
];

return [roteiro.map(function (r) {
    return { payload: { temperatura: r[0], gas: r[1] } };
})];

// SIMULADOR: faz o mesmo que o firmware atual do Wokwi.
// Publica a leitura no tópico de telemetria e, se temperatura > 40 ou gás > 3000,
// publica também o aviso no tópico de alerta (é quando o ESP32 liga o LED e o buzzer).
const l = msg.payload;

const mensagens = [{
    topic: 'parquecoco/ponto1/temperatura',
    payload: { ponto: '1', temperatura: l.temperatura, gas: l.gas }
}];

if (l.temperatura > 40 || l.gas > 3000) {
    mensagens.push({
        topic: 'parquecoco/ponto1/alerta',
        payload: 'Possivel foco de incendio - verificar ponto 1'
    });
}

return [mensagens];
